export const envelope = [32, 26, 24];

export default function build(api) {
  const [W, H, D] = api.size;
  const SEAT_Y = 4;

  // Palette definitions
  const BLUE_ICE = "minecraft:blue_ice";
  const PACKED_ICE = "minecraft:packed_ice";
  const CLEAR_ICE = "minecraft:ice";
  const SNOW_BLOCK = "minecraft:snow_block";
  const SEA_LANTERN = "minecraft:sea_lantern";

  const MORAINE_GRAVEL = api.theme?.ground?.scree || "minecraft:gravel";
  const MORAINE_STONE = api.theme?.stone?.primary || "minecraft:stone";
  const MORAINE_ANDESITE = api.theme?.stone?.accent || "minecraft:andesite";
  const MORAINE_COBBLE = "minecraft:cobblestone";

  // Fast 3D Simplex-style Perlin gradient noise
  const seed = Math.floor(api.random() * 100000) + 713;
  const perm = new Uint8Array(512);
  let s = seed & 0xffff;
  for (let i = 0; i < 256; i++) {
    s = (s * 1664525 + 1013904223) & 0xffffffff;
    perm[i] = i;
  }
  for (let i = 255; i > 0; i--) {
    s = (s * 1664525 + 1013904223) & 0xffffffff;
    const j = Math.abs(s) % (i + 1);
    const tmp = perm[i];
    perm[i] = perm[j];
    perm[j] = tmp;
  }
  for (let i = 0; i < 256; i++) perm[256 + i] = perm[i];

  function grad(hash, x, y, z) {
    const h = hash & 15;
    const u = h < 8 ? x : y;
    const v = h < 4 ? y : h === 12 || h === 14 ? x : z;
    return ((h & 1) === 0 ? u : -u) + ((h & 2) === 0 ? v : -v);
  }

  function noise3D(x, y, z) {
    const X = Math.floor(x) & 255;
    const Y = Math.floor(y) & 255;
    const Z = Math.floor(z) & 255;
    const fx = x - Math.floor(x);
    const fy = y - Math.floor(y);
    const fz = z - Math.floor(z);
    const u = fx * fx * fx * (fx * (fx * 6 - 15) + 10);
    const v = fy * fy * fy * (fy * (fy * 6 - 15) + 10);
    const w = fz * fz * fz * (fz * (fz * 6 - 15) + 10);

    const A = perm[X] + Y, AA = perm[A] + Z, AB = perm[A + 1] + Z;
    const B = perm[X + 1] + Y, BA = perm[B] + Z, BB = perm[B + 1] + Z;

    return (
      (1 - w) * (
        (1 - v) * ((1 - u) * grad(perm[AA], fx, fy, fz) + u * grad(perm[BA], fx - 1, fy, fz)) +
        v * ((1 - u) * grad(perm[AB], fx, fy - 1, fz) + u * grad(perm[BB], fx - 1, fy - 1, fz))
      ) +
      w * (
        (1 - v) * ((1 - u) * grad(perm[AA + 1], fx, fy, fz - 1) + u * grad(perm[BA + 1], fx - 1, fy, fz - 1)) +
        v * ((1 - u) * grad(perm[AB + 1], fx, fy - 1, fz - 1) + u * grad(perm[BB + 1], fx - 1, fy - 1, fz - 1))
      )
    );
  }

  function fbm(x, y, z, octaves = 3) {
    let val = 0;
    let amp = 0.5;
    let freq = 1.0;
    for (let i = 0; i < octaves; i++) {
      val += amp * noise3D(x * freq, y * freq, z * freq);
      amp *= 0.5;
      freq *= 2.0;
    }
    return val;
  }

  // 3D Voxel Grid: 32 x 26 x 24
  const grid = new Array(W * H * D).fill(null);
  function getIndex(x, y, z) {
    return x + W * (y + H * z);
  }
  function setVoxel(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[getIndex(x, y, z)] = block;
    }
  }
  function getVoxel(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[getIndex(x, y, z)];
    }
    return null;
  }

  // 1. Compute Base Glacier Geometry & Snout Morphology
  for (let z = 0; z < D; z++) {
    const relZ = z / (D - 1); // 0 at front, 1 at back
    for (let x = 0; x < W; x++) {
      const relX = (x - 15.5) / 15.5; // -1 to +1
      const isMoraine = Math.abs(relX) > 0.75;
      const moraineDist = Math.max(0, (Math.abs(relX) - 0.75) / 0.25);

      // Top surface of the glacier (U-valley slope + seracs)
      const uShape = Math.pow(Math.abs(relX), 1.8) * 3.2;
      const longitudinalRise = relZ * 4.8;
      const seracNoise = fbm(x * 0.22, z * 0.22, 2.3, 3) * 3.0;
      const topSurfaceY = Math.min(H - 2, Math.floor(16.5 + longitudinalRise + uShape + seracNoise));

      // Front Calving Snout position
      const cliffNoise = fbm(x * 0.35, 1.2, 5.7, 2) * 2.2;
      let snoutZ = 6.8 + cliffNoise;
      if (isMoraine) {
        // Moraines extend further down-valley towards front
        snoutZ -= moraineDist * 4.0;
      }

      // Cavern Portal Geometry
      const caveCenterOffset = Math.sin(z * 0.3) * 1.5;
      const caveCenterX = 15.5 + caveCenterOffset;
      const caveRadiusX = 5.6 - relZ * 1.2;
      const caveBaseY = SEAT_Y;
      const caveArchHeight = 9.8 - relZ * 2.2;

      // Fill Column
      for (let y = 0; y <= topSurfaceY; y++) {
        let isSolid = false;

        // Glacier main body condition
        if (z >= snoutZ) {
          isSolid = true;
        }

        // Calved Iceberg formations in the proglacial forefield (z < snoutZ)
        if (!isSolid) {
          // Berg 1 (West calved monolith)
          const d1 = Math.pow((x - 8) / 3.2, 2) + Math.pow((z - 3.2) / 2.2, 2) + Math.pow((y - SEAT_Y - 2) / 3.0, 2);
          if (d1 <= 1.0) isSolid = true;

          // Berg 2 (East calved pinnacle)
          const d2 = Math.pow((x - 23) / 2.8, 2) + Math.pow((z - 2.8) / 2.0, 2) + Math.pow((y - SEAT_Y - 1.5) / 2.5, 2);
          if (d2 <= 1.0) isSolid = true;

          // Berg 3 (Center submerged shatter)
          const d3 = Math.pow((x - 15) / 2.2, 2) + Math.pow((z - 2.0) / 1.5, 2) + Math.pow((y - SEAT_Y) / 1.8, 2);
          if (d3 <= 1.0) isSolid = true;

          // Berg 4 (Moraine flank ice block west)
          const d4 = Math.pow((x - 3.5) / 2.5, 2) + Math.pow((z - 2.5) / 2.0, 2) + Math.pow((y - SEAT_Y - 1) / 2.2, 2);
          if (d4 <= 1.0) isSolid = true;

          // Berg 5 (Moraine flank ice block east)
          const d5 = Math.pow((x - 28) / 2.5, 2) + Math.pow((z - 2.8) / 2.0, 2) + Math.pow((y - SEAT_Y - 1.5) / 2.6, 2);
          if (d5 <= 1.0) isSolid = true;
        }

        // Hollow out the Subglacial Ice Cave Tunnel
        if (isSolid && z >= 5) {
          const dx = (x - caveCenterX) / caveRadiusX;
          if (Math.abs(dx) < 1.0) {
            const archFactor = Math.pow(1.0 - dx * dx, 0.58) * (1.0 - 0.12 * Math.abs(dx));
            const tunnelNoise = fbm(x * 0.4, y * 0.4, z * 0.35, 2) * 1.0;
            const caveCeilY = caveBaseY + caveArchHeight * archFactor + tunnelNoise;

            // Meltwater river channel floor trough
            const channelBedY = (Math.abs(dx) < 0.4) ? caveBaseY - 1 : caveBaseY;

            if (y >= channelBedY && y <= caveCeilY) {
              isSolid = false;
            }
          }
        }

        // Carve Deep Crevasses across upper glacier surface
        if (isSolid && y >= topSurfaceY - 6) {
          // Transverse Crevasse 1 (mid glacier)
          const crev1Z = 13.0 + Math.sin(x * 0.45) * 1.1;
          if (Math.abs(z - crev1Z) < 0.75 && y >= topSurfaceY - 5) {
            isSolid = false;
          }

          // Transverse Crevasse 2 (upper glacier)
          const crev2Z = 19.2 + Math.cos(x * 0.4) * 0.9;
          if (Math.abs(z - crev2Z) < 0.85 && y >= topSurfaceY - 6) {
            isSolid = false;
          }
        }

        if (isSolid) {
          // Determine Block Substance & Stratigraphy
          let block = PACKED_ICE;

          if (isMoraine) {
            // Lateral Moraine debris till
            const nMor = fbm(x * 0.6, y * 0.6, z * 0.6, 2);
            if (nMor > 0.3) block = MORAINE_GRAVEL;
            else if (nMor > 0.0) block = MORAINE_ANDESITE;
            else if (nMor > -0.3) block = MORAINE_STONE;
            else block = MORAINE_COBBLE;
          } else if (y >= topSurfaceY - 1) {
            // Firn / fresh snow cap on top surface
            block = SNOW_BLOCK;
          } else {
            // Glacial Stratification (blue compression ice bands & clear ice veins)
            const fold = fbm(x * 0.2, y * 0.25, z * 0.2, 3) * 3.5;
            const bandVal = Math.sin(y * 0.75 + z * 0.25 + fold);

            if (y <= SEAT_Y + 1) {
              // Basal compressed ice layer
              block = BLUE_ICE;
            } else if (bandVal > 0.4) {
              block = BLUE_ICE;
            } else if (bandVal < -0.65) {
              block = CLEAR_ICE;
            } else {
              block = PACKED_ICE;
            }
          }

          setVoxel(x, y, z, block);
        }
      }
    }
  }

  // 2. Interior Cave Lining, Sapphire Glow & Meltwater Run
  for (let z = 5; z < D; z++) {
    const relZ = z / (D - 1);
    const caveCenterX = 15.5 + Math.sin(z * 0.3) * 1.5;
    const caveRadiusX = 5.6 - relZ * 1.2;

    for (let x = 0; x < W; x++) {
      const dx = (x - caveCenterX) / caveRadiusX;
      if (Math.abs(dx) <= 1.4) {
        for (let y = SEAT_Y - 1; y < H - 2; y++) {
          const v = getVoxel(x, y, z);
          if (v !== null) {
            // Check if this solid block borders cavern air
            const hasAirNeighbor = (
              getVoxel(x + 1, y, z) === null ||
              getVoxel(x - 1, y, z) === null ||
              getVoxel(x, y + 1, z) === null ||
              getVoxel(x, y - 1, z) === null ||
              getVoxel(x, y, z + 1) === null ||
              getVoxel(x, y, z - 1) === null
            );

            if (hasAirNeighbor) {
              if (y <= SEAT_Y) {
                // Subglacial meltwater river bed
                if (Math.abs(dx) < 0.45) {
                  setVoxel(x, y, z, (x + z) % 3 === 0 ? CLEAR_ICE : BLUE_ICE);
                } else {
                  setVoxel(x, y, z, (x + z) % 2 === 0 ? MORAINE_GRAVEL : BLUE_ICE);
                }
              } else {
                // Glowing blue ice cavern perimeter
                setVoxel(x, y, z, (x * 7 + y * 13 + z * 19) % 5 === 0 ? CLEAR_ICE : BLUE_ICE);
              }
            }
          }
        }
      }
    }
  }

  // 3. Hidden Ethereal Glacial Luminance (Lanterns behind translucent clear ice)
  const glowPoints = [
    [16, 12, 11],
    [12, 10, 15],
    [19, 10, 15],
    [15, 11, 19],
    [17, 9, 22],
    [14, 6, 8],
    [18, 6, 8]
  ];
  for (const [gx, gy, gz] of glowPoints) {
    if (getVoxel(gx, gy, gz) !== null) {
      setVoxel(gx, gy, gz, SEA_LANTERN);
      // Envelope lantern with clear ice for shimmering subglacial glow
      const neighbors = [
        [gx + 1, gy, gz], [gx - 1, gy, gz],
        [gx, gy + 1, gz], [gx, gy - 1, gz],
        [gx, gy, gz + 1], [gx, gy, gz - 1]
      ];
      for (const [nx, ny, nz] of neighbors) {
        if (getVoxel(nx, ny, nz) === PACKED_ICE) {
          setVoxel(nx, ny, nz, CLEAR_ICE);
        }
      }
    }
  }

  // 4. Hanging Glacial Icicle Formations
  // Scans for ceiling air pockets under solid ice blocks
  for (let z = 5; z < D - 1; z++) {
    for (let x = 8; x <= 23; x++) {
      for (let y = SEAT_Y + 2; y < 16; y++) {
        if (getVoxel(x, y, z) === null) {
          const above = getVoxel(x, y + 1, z);
          if (above === BLUE_ICE || above === PACKED_ICE || above === CLEAR_ICE) {
            // Pseudo-random deterministic icicle generation
            const hVal = (x * 37 + y * 17 + z * 59) % 100;
            if (hVal < 28) {
              // 1-block icicle
              setVoxel(x, y, z, "minecraft:pointed_dripstone[vertical_direction=down,thickness=tip]");
            } else if (hVal < 42 && getVoxel(x, y - 1, z) === null) {
              // 2-block icicle
              setVoxel(x, y, z, "minecraft:pointed_dripstone[vertical_direction=down,thickness=frustum]");
              setVoxel(x, y - 1, z, "minecraft:pointed_dripstone[vertical_direction=down,thickness=tip]");
            } else if (hVal < 50 && getVoxel(x, y - 1, z) === null && getVoxel(x, y - 2, z) === null) {
              // 3-block massive ice stalactite
              setVoxel(x, y, z, "minecraft:pointed_dripstone[vertical_direction=down,thickness=base]");
              setVoxel(x, y - 1, z, "minecraft:pointed_dripstone[vertical_direction=down,thickness=frustum]");
              setVoxel(x, y - 2, z, "minecraft:pointed_dripstone[vertical_direction=down,thickness=tip]");
            }
          }
        }
      }
    }
  }

  // 5. Follow Ground Terrain: Foundation / Skirt anchoring down to heightAt (Rule 6)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      // Find lowest solid voxel in column
      let lowestY = -1;
      let highestY = -1;
      for (let y = 0; y < H; y++) {
        const v = getVoxel(x, y, z);
        if (v !== null && !v.startsWith("minecraft:pointed_dripstone")) {
          if (lowestY === -1) lowestY = y;
          highestY = y;
        }
      }

      const hAt = api.heightAt(x, z);
      // Terrain ground level in node coordinates (SEAT_Y is plane 4)
      const terrainGroundY = Math.max(0, Math.min(H - 1, SEAT_Y + Math.floor(hAt)));

      if (lowestY !== -1) {
        // If terrain drops away below the lowest solid block, extend foundation skirt
        if (terrainGroundY < lowestY) {
          const relX = (x - 15.5) / 15.5;
          const isMoraine = Math.abs(relX) > 0.75;
          const mat = isMoraine ? MORAINE_GRAVEL : BLUE_ICE;

          for (let y = terrainGroundY; y < lowestY; y++) {
            setVoxel(x, y, z, mat);
          }
        }
      } else if (z >= 6) {
        // Continuous basal seal along the glacier footprint
        const relX = (x - 15.5) / 15.5;
        const isMoraine = Math.abs(relX) > 0.75;
        const mat = isMoraine ? MORAINE_GRAVEL : BLUE_ICE;
        for (let y = terrainGroundY; y <= SEAT_Y; y++) {
          setVoxel(x, y, z, mat);
        }
      }
    }
  }

  // 6. Ensure Base Monolith Connectivity (Rule 9: One connected solid body)
  // Ensure the basal bed connecting all bergs, portal walls, and moraines is continuous
  for (let z = 0; z < D; z++) {
    for (let x = 0; x < W; x++) {
      const hAt = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(H - 1, SEAT_Y + Math.floor(hAt)));
      if (getVoxel(x, groundY, z) === null && z >= 2) {
        const relX = (x - 15.5) / 15.5;
        const mat = Math.abs(relX) > 0.7 ? MORAINE_GRAVEL : (x % 2 === 0 ? BLUE_ICE : MORAINE_STONE);
        setVoxel(x, groundY, z, mat);
      }
    }
  }

  // 7. Emit Voxels Deterministically to the World API
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = getVoxel(x, y, z);
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Glacial Ice Cave Terminus",
    seatY: SEAT_Y,
    anchors: {
      front: [16, SEAT_Y, 0],
      portal: [16, SEAT_Y, 6],
      crevasse: [16, 20, 13]
    }
  };
}

